// One fixed invoice so the workflow can be executed and demonstrated headlessly.
// If this node was started with data (n8n's manual-run "trigger data"), that data
// is used instead - that is the seam the test harness uses.
const injected = $input.first().json;
const sample = Object.keys(injected).length
  ? injected
  : {
      source: 'manual-demo',
      vendor: 'Northline Electrical Supply',
      amount: '1840.00',
      currency: 'CAD',
      invoice_ref: 'INV-2291',
      notes: 'Panel breakers for Trailer 14 rework. Quoted last month at 1,650.',
    };
return [{ json: sample }];

