  .map((r) => ({
    vendor: String(r.vendor || '').trim(),
    category: String(r.category || '').trim(),
    approved_limit: Number(String(r.approved_limit === undefined ? '' : r.approved_limit).replace(/[^0-9.\-]/g, '')),
    account_active: ['true', 'yes', '1', 'active'].includes(String(r.account_active).trim().toLowerCase()),
