  throw new Error('Config error: approver_email is missing from the Config tab.');
}

const invoice = $('Normalise Intake').first().json;
if (!invoice.currency) invoice.currency = String(config.currency_default || 'CAD').toUpperCase();

return [{ json: { ...invoice, config: { ...config, vendors } } }];

