// The error branch. This is the part most automations leave invisible: the
// execution failed, and the failure is written down with the reason.
const item = $input.first().json;
const message = item.error ?? item.message ?? JSON.stringify(item).slice(0, 800);
const record = {
  queue: 'system_error',
  failed_at: new Date().toISOString(),
  workflow: 'vendor-invoice-approval-gate',
  node: 'AI Agent',
  error: typeof message === 'string' ? message : JSON.stringify(message),
};
return [{ json: { ...record, line: JSON.stringify(record) + '\n' } }];

